CREATE OR REPLACE SNOWFLAKE.ML.FORECAST SDP_ASTRAZENECA_TEASER.SNOWBOTS.M_REVENUE_FC(
  INPUT_DATA => TABLE(SDP_ASTRAZENECA_TEASER.SNOWBOTS.V_REVENUE_HISTORY), SERIES_COLNAME => 'series',
  TIMESTAMP_COLNAME => 'month', TARGET_COLNAME => 'revenue');

SELECT AI_COMPLETE('claude-sonnet-4-5',
  'Write Group Controller commentary using ONLY these figures: ' || OBJECT_CONSTRUCT(*)::STRING)
FROM SDP_ASTRAZENECA_TEASER.SNOWBOTS.VPG_BRIDGE_RESULT_TOP5;

SELECT cc_code, AI_CLASSIFY(cc_name || ' ' || sample_postings,
  (SELECT ARRAY_AGG(label) FROM SDP_ASTRAZENECA_TEASER.PUBLIC.DIM_COST_CENTER WHERE active)) AS mapping
FROM SDP_ASTRAZENECA_TEASER.PUBLIC.V_UNMAPPED_COST_CENTRES;

SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_ASTRAZENECA_TEASER.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-09';

